import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./HomePage.css";
// Add heart icons for favorites
import { Heart, HeartFill } from 'lucide-react';

const HomePage = () => {
  const navigate = useNavigate();

  // Add state for the random quote
  const [quote, setQuote] = useState("");
  // Add state for favorite quotes
  const [favoriteQuotes, setFavoriteQuotes] = useState([]);
  // Add state to show favorites modal
  const [showFavorites, setShowFavorites] = useState(false);
  
  // Create an array of motivational health quotes
  const quotes = [
    "Take care of your body. It's the only place you have to live.",
    "The greatest wealth is health.",
    "Your health is an investment, not an expense.",
    "Healthy eating is a way of life, so it's important to establish routines that are simple, realistically, and ultimately livable.",
    "The food you eat can be either the safest and most powerful form of medicine or the slowest form of poison.",
    "Let food be thy medicine and medicine be thy food.",
    "He who has health has hope, and he who has hope has everything.",
    "If you don't take care of your body, where are you going to live?",
    "Physical fitness is not only one of the most important keys to a healthy body, it is the basis of dynamic and creative intellectual activity.",
    "The doctor of the future will no longer treat the human frame with drugs, but rather will cure and prevent disease with nutrition.",
    "To ensure good health: eat lightly, breathe deeply, live moderately, cultivate cheerfulness, and maintain an interest in life.",
    "The groundwork for all happiness is good health.",
    "A healthy outside starts from the inside.",
    "Good health is not something we can buy. However, it can be an extremely valuable savings account.",
    "Those who think they have no time for healthy eating will sooner or later have to find time for illness.",
  ];
  
  // Load favorite quotes from localStorage on component mount
  useEffect(() => {
    const savedFavorites = localStorage.getItem('favoriteQuotes');
    if (savedFavorites) {
      setFavoriteQuotes(JSON.parse(savedFavorites));
    }
    
    // Select a random quote
    const randomIndex = Math.floor(Math.random() * quotes.length);
    setQuote(quotes[randomIndex]);
  }, []);
  
  // Save favorite quotes to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('favoriteQuotes', JSON.stringify(favoriteQuotes));
  }, [favoriteQuotes]);
  
  // Function to toggle a quote as favorite
  const toggleFavorite = (quoteText) => {
    if (favoriteQuotes.includes(quoteText)) {
      setFavoriteQuotes(favoriteQuotes.filter(q => q !== quoteText));
    } else {
      setFavoriteQuotes([...favoriteQuotes, quoteText]);
    }
  };
  
  // Function to check if a quote is a favorite
  const isFavorite = (quoteText) => {
    return favoriteQuotes.includes(quoteText);
  };
  
  // Function to get a new random quote
  const getNewQuote = () => {
    const randomIndex = Math.floor(Math.random() * quotes.length);
    setQuote(quotes[randomIndex]);
  };

  return (
    <div className="home-container">
      {/* Navigation Bar */}
      <header className="nav-bar">
        <h1 className="logo">Healthy Habits</h1>
        <nav>
          <ul>
            <li><Link to="/dashboard">Dashboard</Link></li>
            <li><Link to="/food-log">Food Log</Link></li>
            <li><Link to="/workouts">Workouts</Link></li>
            <li><Link to="/profile">Profile</Link></li>
            <li><Link to="/settings">Settings</Link></li>
          </ul>
        </nav>
      </header>

      {/* Hero Section */}
      <section className="hero">
        <h2>Track Your Meals. Achieve Your Goals.</h2>
        <p>Join thousands of users making healthy choices every day.</p>
        <button className="cta-button">Get Started</button>
      </section>

      {/* Video Section */}
      <section className="video-section">
        <h3>Motivational Video of the Day</h3>
        <iframe
          width="560"
          height="500"
          src="https://www.youtube.com/embed/_JRefJH6N00?si=grSwgYx8mzCz0jCa"
          title="YouTube video"
          frameBorder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        ></iframe>
      </section>

      {/* Quick Stats Section */}
      <section className="quick-stats">
        <h3>Your Daily Progress</h3>
        <div className="stats-grid">
          <div className="stat-box">
            <p className="stat-number">1200</p>
            <p className="stat-label">Calories Consumed</p>
          </div>
          <div className="stat-box">
            <p className="stat-number">3/5</p>
            <p className="stat-label">Workouts Completed</p>
          </div>
          <div className="stat-box">
            <p className="stat-number">2L</p>
            <p className="stat-label">Water Intake</p>
          </div>
        </div>
      </section>

      {/* Call-to-Action Buttons */}
      <section className="actions">
        <h3>What Would You Like to Do?</h3>
        <button>Log a Meal</button>
        <button>Track a Workout</button>
        <button>View Progress</button>
      </section>

      {/* Enhanced Quote Section - Replacing both old sections */}
      <section className="motivation quote-section">
        <div className="quote-header">
          <h3>Quote of The Day</h3>
          <div className="quote-actions">
            <button 
              className="refresh-quote-btn" 
              onClick={getNewQuote}
              title="Get a new quote"
            >
              ↻
            </button>
            <button 
              className="favorite-btn"
              onClick={() => toggleFavorite(quote)}
              title={isFavorite(quote) ? "Remove from favorites" : "Add to favorites"}
            >
              {isFavorite(quote) ? "★" : "☆"}
            </button>
            <button 
              className="view-favorites-btn"
              onClick={() => setShowFavorites(true)}
              title="View favorite quotes"
            >
              View Favorites
            </button>
          </div>
        </div>
        <blockquote className="quote-text">
          "{quote}"
        </blockquote>
      </section>

      {/* Favorites Modal */}
      {showFavorites && (
        <div className="favorites-modal">
          <div className="favorites-content">
            <div className="favorites-header">
              <h3>Your Favorite Quotes</h3>
              <button 
                className="close-modal-btn"
                onClick={() => setShowFavorites(false)}
              >
                ×
              </button>
            </div>
            {favoriteQuotes.length === 0 ? (
              <p>You haven't saved any favorite quotes yet.</p>
            ) : (
              <ul className="favorites-list">
                {favoriteQuotes.map((favoriteQuote, index) => (
                  <li key={index} className="favorite-quote-item">
                    <p>"{favoriteQuote}"</p>
                    <button 
                      className="remove-favorite-btn"
                      onClick={() => toggleFavorite(favoriteQuote)}
                    >
                      Remove
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}

      {/* Footer */}
      <footer>
        <p>&copy; 2025 Healthy Habits. All Rights Reserved.</p>
      </footer>
    </div>
  );
};

export default HomePage;
